mapper.select:
SELECT DISTINCT date_trunc('month', wh.watch_time)::date FROM public.watch_history wh LEFT JOIN public.video_info vi ON vi.id = wh.video_id AND vi.is_delete = 0 LEFT JOIN public.video_episode ve ON ve.id = wh.episode_id AND ve.is_delete = 0 LEFT JOIN public.user_info u ON u.id = vi.user_id
wh.is_delete = 0 AND wh.user_id = #{userId}
ORDER BY date_trunc('month', wh.watch_time)::date DESC

SELECT video_id
FROM (
    SELECT DISTINCT ON (video_id) video_id, watch_time
    FROM public.watch_history
    WHERE is_delete = 0
      AND user_id = #{userId}
    ORDER BY video_id, watch_time DESC
) t
ORDER BY t.watch_time DESC
LIMIT #{limit}
